import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'

export default defineConfig({
  plugins: [react()],
  server: {
    host: '0.0.0.0',
    port: 8000,
    proxy: {
      '/api': {
        target: 'http://localhost:3000',
        changeOrigin: true,
      },
    },
  },
})

import { useState, useEffect } from 'react'
import './App.css'

function SummaryCard({ readings }) {
  if (!readings.length) return null

  const temps = readings.map(r => r.temperature_c)
  const count = readings.length
  const min = Math.min(...temps)
  const max = Math.max(...temps)
  const avg = (temps.reduce((a, b) => a + b, 0) / temps.length).toFixed(1)

  return (
    <div className="summary-card">
      <h2>📊 Sensor Summary</h2>
      <div className="stats">
        <div className="stat">
          <span className="stat-value">{count}</span>
          <span className="stat-label">Total Readings</span>
        </div>
        <div className="stat">
          <span className="stat-value">{min}°C</span>
          <span className="stat-label">Min Temp</span>
        </div>
        <div className="stat">
          <span className="stat-value">{max}°C</span>
          <span className="stat-label">Max Temp</span>
        </div>
        <div className="stat">
          <span className="stat-value">{avg}°C</span>
          <span className="stat-label">Avg Temp</span>
        </div>
      </div>
    </div>
  )
}

function DataTable({ readings }) {
  if (!readings.length) return null

  return (
    <div className="table-container">
      <h2>📋 Sensor Readings</h2>
      <table>
        <thead>
          <tr>
            <th>Timestamp</th>
            <th>Sensor</th>
            <th>Temperature (°C)</th>
          </tr>
        </thead>
        <tbody>
          {readings.map((r, i) => (
            <tr key={i}>
              <td>{r.timestamp}</td>
              <td>{r.sensor}</td>
              <td>{r.temperature_c}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

export default function App() {
  const [readings, setReadings] = useState([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)

  useEffect(() => {
    fetch('/api/readings')
      .then(res => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`)
        return res.json()
      })
      .then(data => {
        setReadings(data)
        setLoading(false)
      })
      .catch(err => {
        setError(err.message)
        setLoading(false)
      })
  }, [])

  return (
    <div className="app">
      <h1>🌡️ Sensor Dashboard</h1>

      {loading && <p className="loading">Loading sensor data...</p>}
      {error && <p className="error">Error: {error}</p>}

      {!loading && !error && (
        <>
          <SummaryCard readings={readings} />
          <DataTable readings={readings} />
        </>
      )}
    </div>
  )
}

:root {
  --bg: #0f1117;
  --card-bg: #1a1d27;
  --border: #2a2d3a;
  --text: #e4e4e7;
  --text-muted: #a1a1aa;
  --accent: #6366f1;
  --accent-glow: rgba(99, 102, 241, 0.15);
  --green: #22c55e;
  --red: #ef4444;
  --yellow: #eab308;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
}

#root {
  max-width: 960px;
  margin: 0 auto;
  padding: 2rem 1rem;
}

/* Header */
.header {
  text-align: center;
  margin-bottom: 2rem;
}

.header h1 {
  font-size: 1.75rem;
  font-weight: 700;
  background: linear-gradient(135deg, var(--accent), #a78bfa);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  margin-bottom: 0.25rem;
}

.header p {
  color: var(--text-muted);
  font-size: 0.9rem;
}

/* Summary Cards */
.summary {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
  margin-bottom: 2rem;
}

.summary-card {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 1.25rem;
  text-align: center;
  transition: border-color 0.2s;
}

.summary-card:hover {
  border-color: var(--accent);
}

.summary-card .label {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  margin-bottom: 0.5rem;
}

.summary-card .value {
  font-size: 1.75rem;
  font-weight: 700;
}

.summary-card .value.count {
  color: var(--accent);
}

.summary-card .value.min {
  color: var(--green);
}

.summary-card .value.max {
  color: var(--red);
}

/* Table */
.table-wrapper {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 12px;
  overflow: hidden;
}

.table-wrapper h2 {
  padding: 1rem 1.25rem;
  font-size: 1rem;
  font-weight: 600;
  border-bottom: 1px solid var(--border);
}

table {
  width: 100%;
  border-collapse: collapse;
}

thead th {
  padding: 0.75rem 1.25rem;
  text-align: left;
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
  background: rgba(255, 255, 255, 0.02);
  border-bottom: 1px solid var(--border);
}

tbody td {
  padding: 0.65rem 1.25rem;
  font-size: 0.875rem;
  border-bottom: 1px solid var(--border);
}

tbody tr:last-child td {
  border-bottom: none;
}

tbody tr:hover {
  background: var(--accent-glow);
}

.sensor-badge {
  display: inline-block;
  padding: 0.15rem 0.5rem;
  border-radius: 6px;
  font-size: 0.75rem;
  font-weight: 600;
  background: rgba(99, 102, 241, 0.15);
  color: var(--accent);
}

.temp-cell {
  font-variant-numeric: tabular-nums;
  font-weight: 500;
}

/* Loading / Error */
.status {
  text-align: center;
  padding: 3rem;
  color: var(--text-muted);
  font-size: 1rem;
}

.status.error {
  color: var(--red);
}

/* Responsive */
@media (max-width: 600px) {
  .summary {
    grid-template-columns: 1fr;
  }
}
